		names:       []string{"bragi"},
		defaultName: "bragi",
	}
	svc := newTestService(t, ServiceOptions{ServiceConfig: sc})

	infos, err := svc.ListModels(context.Background(), ModelFilter{})
	if err != nil {
		t.Fatalf("ListModels: %v", err)
	}

	var defaultCount int
	for _, info := range infos {
		if info.IsDefault {
			defaultCount++
			if info.ID != "default-model" {
